CREATE TABLE "CuratorShop" ("userId" TEXT PRIMARY KEY, "title" TEXT NOT NULL, "introduction" TEXT NOT NULL DEFAULT '', "isPublic" BOOLEAN NOT NULL DEFAULT false, "version" INTEGER NOT NULL DEFAULT 1, CONSTRAINT "CuratorShop_userId_fkey" FOREIGN KEY ("userId") REFERENCES "User"("id") ON DELETE CASCADE ON UPDATE CASCADE);
CREATE TABLE "CuratorShopEntry" ("userId" TEXT NOT NULL, "workId" TEXT NOT NULL, "position" INTEGER NOT NULL, "note" TEXT NOT NULL DEFAULT '', "retailerUrl" TEXT NOT NULL DEFAULT '', "affiliate" BOOLEAN NOT NULL DEFAULT false, PRIMARY KEY ("userId","workId"), CONSTRAINT "CuratorShopEntry_userId_fkey" FOREIGN KEY ("userId") REFERENCES "CuratorShop"("userId") ON DELETE CASCADE ON UPDATE CASCADE, CONSTRAINT "CuratorShopEntry_workId_fkey" FOREIGN KEY ("workId") REFERENCES "Work"("id") ON DELETE CASCADE ON UPDATE CASCADE);
CREATE UNIQUE INDEX "CuratorShopEntry_userId_position_key" ON "CuratorShopEntry"("userId","position");
CREATE INDEX "CuratorShopEntry_workId_idx" ON "CuratorShopEntry"("workId");
